def bubble_sort(values):
    boundary = len(values) - 1
    while True:
        no_swaps = True
        for j in range(boundary):
            if values[j] > values[j + 1]:
                values[j], values[j + 1] = values[j + 1], values[j]
                no_swaps = False
        boundary -= 1
        if no_swaps:
            return values

assert bubble_sort([3, 1, 4, 6, 5, 8]) == [1, 3, 4, 5, 6, 8]
assert bubble_sort([7, 3, 9, 1, 5]) == [1, 3, 5, 7, 9]
